from collections import deque
H,W=25,13
def comps(g,val):
    seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==val and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==val and not seen[x][y]:
                            seen[x][y]=True; q.append((x,y))
                out.append(cells)
    return out
